import {HEROES,ELEMENTS,ARRAYS,MODES,TWIN_BLOOMS,getHero} from './data.js';
import * as Store from './state.js';
import {createBattle,castSkill,endTurn,autoAction,buyEncounter} from './combat.js';
import {Effects} from './fx.js';
import {HERO_ART} from '../assets/hero-art.js';

let state=Store.loadSave(), screen='home', filter='all', selectedHero='su_lianhua', formationSlot=0, modeId='hunt', difficulty=1, battle=null, selectedSkill=null, busy=false, auto=false, modal=null, reward=null;
const game=document.querySelector('#game');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=v=>Number(v||0).toLocaleString('en-US');
const costs=value=>Object.entries(value||{}).map(([key,n])=>num(n)+' '+({stones:'Spirit Stones',jade:'Jade',incense:'Fate Incense',merit:'Merit',pills:'Spirit Pills',essence:'Essence',scrolls:'Scrolls',dew:'Blossom Dew',dust:'Forging Dust',herbs:'Spirit Herbs'}[key]||key)).join(' · ');
const statText=(key,value)=>key.toUpperCase()+' +'+(['crit','critDamage'].includes(key)?(value*100).toFixed(1)+'%':num(value));
const paths={lotus:'M24 40C6 40 3 24 4 20c12 0 18 6 20 16M24 40c18 0 21-16 20-20-12 0-18 6-20 16M24 36C10 26 18 10 24 4c6 6 14 22 0 32M10 44h28',sword:'M10 38 35 8l8-3-3 9-25 29M7 31l12 12M5 43l5-5',book:'M24 12C16 6 9 7 4 10v30c7-4 13-3 20 1 7-4 13-5 20-1V10c-7-3-14-3-20 2v29M9 15l10 1M9 22l10 1M29 16l10-1M29 23l10-1',temple:'M5 18 24 6l19 12M2 20h44M9 22v18m10-18v18m10-18v18m10-18v18M3 41h42M7 45h34M12 8h24',diamond:'M24 3 40 23 24 45 8 23 24 3ZM8 23h32M24 3l-7 20 7 22 7-22-7-20',coins:'M10 16c0-9 30-9 30 0s-30 9-30 0Zm0 0v17c0 10 30 10 30 0V16M10 24c0 9 30 9 30 0',star:'m24 3 6 14 15 2-11 11 3 15-13-8-13 8 3-15L3 19l15-2Z',mail:'M4 10h40v29H4V10Zm0 1 20 16 20-16',bell:'M9 32h30l-4-7V17c0-14-22-14-22 0v8l-4 7Zm9 6c0 8 12 8 12 0M24 3V0',settings:'M24 15a9 9 0 1 0 0 18 9 9 0 0 0 0-18ZM24 3v6m0 30v6M3 24h6m30 0h6M9 9l5 5m20 20 5 5M9 39l5-5m20-20 5-5',arrow:'M38 24H8m14-14L8 24l14 14',team:'M24 5a7 7 0 1 0 0 14 7 7 0 0 0 0-14ZM10 13a6 6 0 1 0 0 12M38 13a6 6 0 1 1 0 12M13 43V31c0-12 22-12 22 0v12M3 43V31c0-6 5-8 10-7m32 19V31c0-6-5-8-10-7',scroll:'M12 6h24v36H12V6Zm-5 0h34M7 42h34M17 16h14M17 23h14M17 30h9',gift:'M4 20h40v8H4v-8Zm4 8v16h32V28M24 20v24M24 20C3 20 7 1 17 8l7 12Zm0 0C45 20 41 1 31 8L24 20Z',bag:'M16 3h16l-4 10c20 16 18 31-4 31S0 29 20 13L16 3Zm2 11h12M24 22v15m-5-12h8m-8 8h8',flame:'M25 3C12 14 24 17 12 23 1 32 15 47 27 44S47 25 33 16c2 14-13 8-8-13Z',compass:'M24 3a21 21 0 1 0 .1 0ZM31 16l-4 13-12 4 4-13 12-4Z',shield:'M24 3 42 10v14c0 10-18 21-18 21S6 34 6 24V10L24 3Z',close:'M10 10l28 28M38 10 10 38',check:'m8 24 11 11L41 12',play:'M15 7v34l28-17L15 7Z',save:'M8 5h28l7 8v30H5V5h3Zm5 0v14h22V5M13 43V28h22v15'};
const GOLD_ICONS={temple:0,star:1,book:2,team:3,sect:4,bag:5,mail:6,bell:7,settings:8,scroll:9,lantern:10,gift:11};
function icon(name,cls=''){
  if(name in GOLD_ICONS){const cell=GOLD_ICONS[name];return '<span class="icon illustrated-icon '+cls+'" style="--ix:'+((cell%4)*100/3)+'%;--iy:'+(Math.floor(cell/4)*50)+'%" aria-hidden="true"></span>';}
  return '<svg class="icon '+cls+'" viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[name]||paths.lotus)+'"/></svg>';
}
function button(label,action,cls='',data=''){return `<button class="btn ${cls}" data-action="${action}" ${data}>${label}</button>`;}
function art(key,cls=''){const a=HERO_ART[key];return `<div class="hero-art art-${esc(key)} ${cls}" ${a?`style="background-image:url('${a.file}');background-position:${a.position};background-size:${a.size}"`:''}></div>`;}
function phase(element){const e=ELEMENTS[element]||ELEMENTS.earth;return `<span class="phase" style="--phase:${e.color}" title="${e.name}">${e.glyph}</span>`;}
function card(hero,{small=false,owned=state.heroes[hero.id],action='hero',data='',selected=false}={}){return `<button class="hero-card ${small?'small':''} ${selected?'selected':''} rarity-${hero.rarity}" data-action="${action}" data-id="${hero.id}" ${data} style="--phase:${ELEMENTS[hero.element].color}">${art(hero.id)}<div class="foil"></div><span class="card-corner tl"></span><span class="card-corner tr"></span><span class="card-corner bl"></span><span class="card-corner br"></span>${phase(hero.element)}<span class="card-level">${owned?'Lv. '+owned.level:'未'}</span><div class="card-caption"><strong>${hero.name}</strong>${!small?`<span>${hero.title}</span>`:''}<span class="stars">${'✦'.repeat(hero.rarity)}</span></div></button>`;}
function header(){
  const xpGoal=state.player.level*100;
  return '<header class="topbar"><button class="profile" data-action="profile"><div class="portrait">'+art('lotus')+'</div><div class="profile-info"><strong>'+esc(state.player.name||'Pavilion Master')+'</strong><span class="profile-crest">'+icon('sect')+'</span><div class="xp"><i style="width:'+Math.min(100,state.player.xp/xpGoal*100)+'%"></i></div><span class="profile-sub">'+num(state.player.xp)+' / '+num(xpGoal)+' EXP</span></div><span class="player-level">'+state.player.level+'</span></button><div class="currencies">'+[['stones','Spirit Stones'],['jade','Immortal Jade'],['incense','Fate Incense'],['dew','Blossom Dew']].map(([key,label])=>'<button class="currency '+key+'" data-action="currency" data-id="'+key+'" title="'+label+'"><span class="currency-art currency-art-'+key+'" aria-hidden="true"></span><strong>'+num(state.currencies[key])+'</strong><span class="currency-plus">+</span></button>').join('')+'</div><div class="top-actions"><button class="round" aria-label="Jade Slips" data-action="mail">'+icon('mail')+'<b class="notice">2</b></button><button class="round" aria-label="Daily rewards" data-action="daily">'+icon('bell')+'</button><button class="round" aria-label="Settings" data-action="settings">'+icon('settings')+'</button></div></header>';
}
const navItems=[['home','temple','Pavilion'],['summon','star','Fate Pond'],['collection','book','Collection'],['formation','team','Formation'],['sect','sect','Sect'],['inventory','bag','Storage']];
function nav(){return `<nav class="bottom-nav">${navItems.map(([id,i,label])=>`<button class="nav-item ${screen===id?'active':''}" data-action="navigate" data-screen="${id}">${icon(i)}<span>${label}</span></button>`).join('')}</nav>`;}
function title(text,sub=''){return `<div class="page-title"><button class="round back" aria-label="Back to Pavilion" data-action="navigate" data-screen="home">${icon('arrow')}</button><div><h1>${text}</h1>${sub?`<span>${sub}</span>`:''}</div></div>`;}
function home(){return   '<aside class="home-left">'+button('<span class="menu-badge">'+icon('scroll')+'</span><span>Duties</span>','duties','parchment')+button('<span class="menu-badge">'+icon('lantern')+'</span><span>Ascension</span>','ascension','parchment')+button('<span class="menu-badge">'+icon('sect')+'</span><span>Sect</span>','navigate','parchment','data-screen="sect"')+'</aside>'+ 
  '<div class="celestial-seal" aria-hidden="true"><span>仙<br>宗</span></div>'+ 
  '<aside class="home-right"><button class="featured-mode ornamental" data-action="navigate" data-screen="modes"><div class="mode-art mode-home-realms"></div><div class="featured-mode-title">'+icon('compass')+'<strong>Realms & Trials</strong></div></button><div class="home-shortcuts">'+button(icon('star')+'<span>Summon</span>','navigate','','data-screen="summon"')+button(icon('book')+'<span>Collection</span>','navigate','','data-screen="collection"')+button(icon('team')+'<span>Formation</span>','navigate','','data-screen="formation"')+'</div>'+button('<span>Begin</span><b aria-hidden="true">»</b>','navigate','primary begin','data-screen="modes"')+'</aside>'+ 
  '<button class="event-banner ornamental" data-action="ascension"><div class="event-art"><div class="hero-art art-enemy_phoenix"></div></div><div class="event-copy"><span class="eyebrow">Pavilion Rewards</span><strong>Path of<br>Ascension</strong><span>Every tier is free &nbsp; ❯</span></div><span class="banner-dots"><i></i><i></i><i></i></span></button>'+ 
  '<div class="home-team"><span class="ribbon">My formation</span><div>'+state.team.map(id=>card(getHero(id),{small:true})).join('')+'<button class="edit-team" aria-label="Edit formation" data-action="navigate" data-screen="formation">✎</button></div></div>'+ 
  '<div class="offline-tag">'+(state.activeBattle?button('Resume saved trial','resume-battle','subtle'):'<span></span> Offline · Saved on this PC')+'</div>';
}
function modes(){return `${title('Realms & Trials','Every path leads closer to immortality')}<aside class="modes-menu">${button(icon('arrow')+'Back','navigate','parchment','data-screen="home"')}${button(icon('gift')+'Rewards','duties','parchment')}${button(icon('shield')+'Records','records','parchment')}</aside><div class="modes-grid">${MODES.map(m=>`<button class="mode-tile ornamental" data-action="mode" data-id="${m.id}"><div class="mode-art mode-${m.id}"></div><span class="mode-tag">${m.tag}</span><div class="mode-title">${icon(({hunt:'sword',pagoda:'temple',realm:'compass',shrine:'lotus',tournament:'shield',raid:'flame'})[m.id])}<strong>${m.name}</strong></div><div class="mode-bottom"><span>${m.reward}</span><span>❯</span></div></button>`).join('')}</div><div class="modes-note">${icon('lotus')} Unlimited adventures. No stamina. Every reward earned in play.</div>`;}
function summonScreen(){const featured=getHero('gui_chanjuan');return `${title('Fate Pond','Where a thousand threads become one')}<aside class="summon-tabs"><div class="selected ornamental">${icon('lotus')}<strong>Celestial<br>Blossoms</strong><span>Permanent fate pond</span></div>${button(icon('book')+'Summon history','history','parchment')}${button(icon('diamond')+'Rates & guarantees','rates','parchment')}</aside><div class="summon-heading"><span class="banner-tag">Featured Celestial · ${featured.name}</span><h1>Moonlit Osmanthus</h1><p>“Even the moon remembers<br>the flowers that bloomed beneath it.”</p><span class="summon-stars">✦ ✦ ✦ ✦ ✦</span></div><div class="summon-showcase">${[featured,getHero('shang_jianlan'),getHero('wei_zi')].map(h=>card(h,{small:true})).join('')}</div><aside class="pity-panel ornamental"><span class="eyebrow">THREADS OF DESTINY</span><strong>${state.pity}<small> / 60</small></strong><div class="meter"><i style="width:${state.pity/60*100}%"></i></div><p>A Celestial Blossom is guaranteed<br>within ${60-state.pity} summons.</p><div class="fate-points"><span>Thread of Fate</span><b>${state.fatePoints} / 120</b></div>${button('Choose a Celestial','fate-select','subtle')}<span class="fine">All heroines remain obtainable.</span></aside><div class="summon-actions">${button('Summon ×1 <small>'+icon('scroll')+' 1 Fate Incense</small>','summon','jade','data-count="1"')}${button('Summon ×10 <small>'+icon('scroll')+' 10 Fate Incense</small>','summon','primary','data-count="10"')}<span>Ten summons guarantee a 4★ or better · Duplicates awaken Dao petals</span></div>`;}
function collection(){const heroes=HEROES.filter(h=>filter==='all'||filter==='owned'&&state.heroes[h.id]||h.element===filter);return `${title('The Hundred Blossoms',Object.keys(state.heroes).length+' / '+HEROES.length+' immortals gathered')}<div class="filter-bar">${[['all','All Blossoms'],['owned','Owned'],...Object.entries(ELEMENTS).filter(([k])=>!['yin','yang'].includes(k)).map(([k,v])=>[k,v.glyph+' '+v.name])].map(([id,label])=>button(label,'filter',filter===id?'active':'',`data-id="${id}"`)).join('')}</div><div class="collection-grid scroll-area">${heroes.map(h=>`<div class="collection-entry ${state.heroes[h.id]?'':'unowned'}">${card(h)}<span>${h.path} · ${state.heroes[h.id]?'Owned':'Undiscovered'}</span></div>`).join('')}</div>`;}
function formation(){const stats=state.team.map(id=>Store.getHeroStats(state,id));const total=k=>stats.reduce((a,s)=>a+(s[k]||0),0);const array=ARRAYS.find(a=>a.id===state.array)||ARRAYS[0];return `${title('Formation','Four immortals. One harmonious Dao.')}<div class="formation-tabs">${ARRAYS.map(a=>button(a.name,'array',a.id===state.array?'active':'',`data-id="${a.id}"`)).join('')}</div><div class="formation-board"><div class="array-disc"><span>阵</span></div>${state.team.map((id,i)=>`<div class="formation-position pos-${i} ${formationSlot===i?'focused':''}"><div class="slot-label">${i===0?'✦ Formation leader':'Position '+(i+1)}</div>${card(getHero(id),{action:'slot',data:`data-slot="${i}"`,selected:formationSlot===i})}</div>`).join('')}</div><aside class="formation-stats parchment-panel"><span class="eyebrow">Formation power</span><h2>${num(Store.getPower(state))}</h2><hr><h3>Elemental harmony</h3><div class="harmony-preview">${state.team.map(id=>phase(getHero(id).element)).join('<span>›</span>')}</div><p>Water → Wood → Fire → Earth<br>Chain four techniques for +45% power.</p><hr>${[['hp','Vitality'],['atk','Attack'],['def','Defense'],['haste','Haste']].map(([key,label])=>`<div class="stat-line"><span>${label}</span><strong>${num(total(key))}</strong></div>`).join('')}<hr><h3>${array.name}</h3><p>${array.description}</p><h3>Twin Blooms</h3>${TWIN_BLOOMS.filter(t=>t.heroes.every(id=>state.team.includes(id))).map(t=>`<p class="twin">✦ ${t.name}</p>`).join('')||'<p>Pair kindred immortals to unlock a bond.</p>'}</aside><div class="formation-roster"><span>Select a position, then a Blossom to assign</span><div>${HEROES.filter(h=>state.heroes[h.id]).map(h=>card(h,{small:true,action:'assign',selected:state.team.includes(h.id)})).join('')}</div></div><div class="formation-actions">${button(icon('compass')+'Auto formation','auto-team','parchment')}${button(icon('save')+'Save formation','save-team','jade')}${button('Enter the Realms ❯','navigate','primary','data-screen="modes"')}</div>`;}
function sect(){const idle=Store.getOfflineRewards(state);return `${title('Hundred Blossoms Pavilion','Cultivate together. Rise beyond the heavens.')}<div class="sect-intro ornamental"><span class="eyebrow">YOUR HOME AMONG THE CLOUDS</span><h2>A sanctuary for every Blossom</h2><p>The Pavilion gathers resources for up to twelve hours.<br>${num(idle.stones)} spirit stones · ${num(idle.herbs)} herbs · ${num(idle.exp)} cultivation EXP ready</p>${button(icon('gift')+'Gather idle rewards','idle','jade')}</div><div class="buildings-grid">${Store.BUILDINGS.map((b,i)=>`<article class="building ornamental"><span class="building-icon">${icon(['temple','lotus','flame','sword','compass','book'][i%6])}</span><span class="eyebrow">LEVEL ${state.buildings[b.id]||1}</span><h3>${b.name}</h3><p>${b.description}</p>${button('Improve · '+num(3000*state.buildings[b.id]**2)+' stones','building','subtle',`data-id="${b.id}"`)}${({alchemy:button('Brew spirit pills','alchemy','jade'),forge:button('Craft equipment','forge','jade'),missions:button('Manage expeditions','expeditions','jade'),tea:button('Share tea','hero','jade','data-id="su_lianhua"'),scripture:button('Browse Blossoms','navigate','jade','data-screen="collection"')})[b.id]||''}</article>`).join('')}</div>`;}
function inventory(){return `${title('Storage Ring',state.inventory.length+' treasures · Ten equipment slots per immortal')}<div class="inventory-actions">${button(icon('bag')+'Merit Exchange','shop','jade')}${button(icon('sword')+'Artefact Forge','forge','subtle')}</div><div class="inventory-grid scroll-area">${state.inventory.map(g=>`<button class="gear-item ornamental" data-action="gear" data-id="${g.id}"><span class="gear-symbol">${icon(g.slot==='weapon'?'sword':g.slot?.includes('ring')?'diamond':'shield')}</span><span class="gear-rarity">${g.rarity} · +${g.level||0}</span><strong>${g.name}</strong><span>${g.set||''} · ${g.slot}</span><small>${Object.entries(g.stats||{}).map(([k,v])=>statText(k,v)).join(' · ')}</small></button>`).join('')||'<div class="empty-state">Your storage ring awaits its first treasure.<br>Win a Demon Hunt to discover equipment.</div>'}</div>`;}
function realmScreen(){const run=state.realmRun;const ended=run&&['complete','defeat'].includes(run.status);let content='';if(!run||ended){content=`<p>${run?.status==='complete'?'The guardian has fallen. Your expedition rewards—320 Jade, 3 Fate Incense and 10 Dao Marks—have been received.':run?.status==='defeat'?'Your expedition has ended. The knowledge and treasures you gathered remain with your sect.':'Victories lead to blessings, sanctuaries and stronger guardians. Your choices shape this expedition.'}</p>${button(run?'Begin a new expedition':'Begin expedition','realm-start','primary')}`;}else if(run.status==='blessing'){content=`<p>Your victory has revealed a gift. Choose one blessing before continuing.</p>${button('Choose a blessing','realm-blessing','primary')}`;}else if(run.status==='battle'){content=`<p>A guardian awaits on the chosen path.</p>${button(state.activeBattle?'Resume trial':'Enter the encounter',state.activeBattle?'resume-battle':'realm-enter','primary')}`;}else{content=`<p>Choose your next path. Health carries between encounters; a Lotus Spring restores it.</p><div class="realm-nodes">${run.nodes.map((n,i)=>button(icon(n.type==='camp'?'lotus':n.type==='treasure'?'gift':'sword')+`<strong>${n.name}</strong><span>${n.description}</span>`,'realm-node','',`data-index="${i}"`)).join('')}</div>`;}return `${title('Secret Realm','A different journey beyond every gate')}<div class="realm-route ornamental"><span class="eyebrow">THE JADE LABYRINTH</span><h2>${run&&!ended?'Depth '+run.floor+' / '+run.maxFloors:run?.status==='complete'?'Realm conquered':'Step beyond the veil'}</h2>${content}<div class="realm-blessings">${(run?.blessings||[]).map(id=>`<span title="${esc(Store.REALM_BLESSINGS.find(b=>b.id===id)?.description||'')}">✦ ${Store.REALM_BLESSINGS.find(b=>b.id===id)?.name||id}</span>`).join('')}</div>${run&&!ended?button('Abandon expedition','realm-abandon','subtle'):''}</div>`;}
function battleCard(u,enemy=false){
  const h=getHero(u.id)||u,hp=Math.max(0,u.hp/u.maxHp*100),chosen=selectedSkill&&battle.allies.find(a=>a.uid===selectedSkill.actorId)?.skills[selectedSkill.skillIndex];
  const targetable=chosen&&u.hp>0&&(chosen.target.includes('allies')||chosen.target==='ally'?!enemy:enemy);
  return `<div class="battle-card ${enemy?'enemy':'ally'} ${u.hp<=0?'fallen':''} ${u.boss?'boss':''} ${targetable?'targetable':''}" data-uid="${u.uid}" data-display-hp="${u.hp}" data-max-hp="${u.maxHp}" style="--phase:${(ELEMENTS[u.element]||ELEMENTS.earth).color}${targetable?';outline:2px solid var(--phase);outline-offset:4px':''}"><button class="battle-target" data-action="target" data-uid="${u.uid}" aria-label="${targetable?'Target':'Inspect'} ${esc(u.name)}">${u.boss&&!u.id.startsWith('heart_')?'<div class="boss-art"></div>':art(enemy&&!getHero(u.id)&&!u.id.startsWith('heart_')?({fire:'enemy_phoenix',water:'enemy_fox',wood:'enemy_stag',earth:'enemy_guardian',metal:'enemy_wraith'})[u.element]:(HERO_ART[u.id]?u.id:HERO_ART[u.id.replace(/^heart_/,'')]?u.id.replace(/^heart_/,''):(u.art||h.art||'thunder')))}${phase(u.element)}<span class="card-level">${u.boss?'BOSS':'Lv. '+u.level}</span><span class="battle-name">${esc(u.name)}</span></button>${u.boss?`<div class="qi-shield" title="Qi shield: ${u.qiShield} / ${u.maxQiShield}. Break it to delay the ultimate.">${Array.from({length:u.maxQiShield||12},(_,i)=>`<i class="${i<u.qiShield?'filled':''}"></i>`).join('')}</div><div class="boss-countdown" style="text-align:center;color:#ffd99b;font-size:11px;letter-spacing:1px;padding:3px">ULTIMATE IN ${u.ultimateCountdown??u.cooldowns[2]} TURN${u.cooldowns[2]===1?'':'S'}</div>`:''}<div class="battle-skills">${u.skills.map((s,i)=>`<button class="skill ${u.cooldowns[i]>0?'cooldown':''} ${selectedSkill?.actorId===u.uid&&selectedSkill?.skillIndex===i?'armed':''}" data-action="skill" data-uid="${u.uid}" data-index="${i}" ${enemy||u.hp<=0?'disabled':''} title="${esc(s.name+' — '+(s.description||''))}${u.skipped?' · Sealed this turn':''}"><span class="skill-glyph">${['✧','❖','✺'][i]}</span><span>${esc(s.name)}</span>${u.cooldowns[i]>0?`<b>${u.cooldowns[i]}</b>`:`<small>${i+1}</small>`}</button>`).join('')}</div><div class="health"><i style="width:${hp}%"></i><span>${num(Math.max(0,u.hp))} / ${num(u.maxHp)}</span></div><div class="statuses">${(u.statuses||[]).map(s=>`<span style="color:${s.buff?'#a8efbb':'#ffb4a0'}" title="${esc(s.name||s.id)} · ${s.turns} turn(s)">${esc((s.name||s.id).slice(0,2))} ${s.turns??''}</span>`).join('')}${u.shield>0?`<span title="Spirit Shield">◇ ${Math.round(u.shield)}</span>`:''}${(u.passives||[]).map((p,i)=>`<span class="passive-seal" style="opacity:${u.level>=(i?50:30)?1:.4}" title="${esc(p.name)} · ${u.level>=(i?50:30)?esc(p.description):'Unlocks at level '+(i?50:30)}">${u.level>=(i?50:30)?'✥':'◇'}</span>`).join('')}</div></div>`;
}
function battleScreen(){return `<div class="combat-top"><button class="round" aria-label="Leave battle" data-action="leave-battle">${icon('arrow')}</button><div><span class="eyebrow">${MODES.find(m=>m.id===battle.mode)?.name||'Heavenly Trial'}</span><h2>Stage ${battle.level} <small>Wave ${battle.wave} / ${battle.totalWaves}</small></h2></div><div class="phase-pool">${Object.entries(ELEMENTS).slice(0,5).map(([k])=>`<div>${phase(k)}<b>${battle.phaseQi?.[k]??0}</b></div>`).join('')}</div><span class="combat-round">ROUND <b>${battle.round}</b></span></div><div class="battle-board"><div class="enemy-row">${battle.enemies.map(u=>battleCard(u,true)).join('')}</div><div class="battle-divider"><span>${selectedSkill?'Choose a target · Click the technique again for area skills':busy?'The heavens stir…':'Cast your ready techniques in any order'}</span></div><div class="ally-row">${battle.allies.map(u=>battleCard(u)).join('')}</div></div><aside class="combat-sidebar"><div class="battle-seal"><span>戰</span></div><div class="qi-display">${icon('flame')}<strong>${battle.qi}<small> / 30</small></strong><span>SPIRIT QI</span></div><div class="harmony-display"><span>HARMONY</span><strong>×${battle.harmony||1}</strong><small>${battle.lastElement?ELEMENTS[battle.lastElement]?.name+' → '+ELEMENTS[ELEMENTS[battle.lastElement]?.feeds]?.name:'Begin an elemental chain'}</small></div><label class="empower-toggle"><input id="empower" type="checkbox" ${battle.uiEmpower?'checked':''}>Empower technique <small>S2: 6 Qi · Ultimate: 10 Qi</small></label>${button(icon('play')+(busy?'Resolving…':'End turn'),'end-turn','primary',busy?'disabled':'')}${button(auto?'Stop auto battle':'Auto battle','auto','subtle '+(auto?'active':''))}<div class="battle-options">${button('×'+state.settings.speed,'speed','subtle')}${button(icon('book'),'battle-log','subtle','aria-label="Battle log"')}</div>${battle.encounters?.length&&!battle.encounterPurchased?button('✧ Fortuitous encounter','encounter','encounter-button'):''}</aside><div class="battle-footer">${icon('lotus')} Water → Wood → Fire → Earth → Metal <span>SPACE · End turn &nbsp; A · Auto &nbsp; ESC · Pause</span></div>`;}
function render(){const views={home,modes,summon:summonScreen,collection,formation,sect,inventory,realm:realmScreen,battle:battleScreen};const isBattle=screen==='battle';game.innerHTML=`<div id="stage" class="screen-${screen} ${state.settings.reducedMotion?'reduce-motion':''}"><div class="scene-background ${screen==='home'||screen==='summon'?'splash':''}"></div><div class="scene-shade"></div><div class="edge-flourish top-left"></div><div class="edge-flourish bottom-right"></div><div class="ambient">${Array.from({length:18},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div>${isBattle?'':header()}<section class="screen-content">${(views[screen]||home)()}</section>${isBattle?'':nav()}<canvas id="effects" width="1600" height="900"></canvas><div id="float-layer"></div><div id="cutin-layer"></div><div id="modal-layer">${modal?modalMarkup():''}</div><div id="toast" role="status"></div></div>`;fx.canvas=document.querySelector('#effects');fx.ctx=fx.canvas.getContext('2d');resize();}
function resize(){const stage=document.querySelector('#stage');if(stage)stage.style.transform=`translate(-50%,-50%) scale(${Math.min(innerWidth/1600,innerHeight/900)})`;}
const fx=new Effects(document.createElement('canvas'),()=>state.settings);
function persist(){if(Store.saveGame(state)===false&&document.querySelector('#toast'))toast(state.saveWarning||'Save could not be written. Export a backup from Settings.');}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3200);}
function openModal(type,data={}){modal={type,...data};document.querySelector('#modal-layer').innerHTML=modalMarkup();}
function closeModal(){if(modal?.type==='save-warning'){delete state.saveWarning;Store.saveGame(state);}modal=null;document.querySelector('#modal-layer').innerHTML='';}
function act(result,message){if(result?.ok===false){toast(result.reason||'That action is not available yet.');return false;}persist();render();if(message)toast(message);return true;}
function navigate(to){screen=to;modal=null;selectedSkill=null;auto=false;persist();render();}
function modalMarkup(){let body='',heading='',cls='';const m=modal;
  if(m.type==='records'){heading='Records of the Pavilion';body='<p>Your highest conquered trials, saved on this PC.</p><div class="records-list">'+MODES.map(mode=>'<div>'+icon(mode.id==='pagoda'?'temple':'shield')+'<strong>'+mode.name+'</strong><span>'+(state.progress[mode.id]?'Stage '+state.progress[mode.id]:'Unchallenged')+'</span></div>').join('')+'</div>';}
  if(m.type==='save-warning'){heading='Save recovery';body=`<p>${esc(state.saveWarning)}</p><p>Your recovery copy is retained on this PC. Use Settings to import a known backup or export your recovered progress.</p>${button('Continue','close','jade')}`;}
  if(m.type==='hero'){const h=getHero(m.id),o=state.heroes[h.id],stats=o?Store.getHeroStats(state,h.id):h.base;heading=h.name;cls='hero-modal';body=`<div class="hero-detail-art">${art(h.id)}<div>${phase(h.element)}<span>${h.title}</span><b class="stars">${'✦'.repeat(h.rarity)}</b></div></div><div class="hero-detail-content scroll-area"><span class="eyebrow">${h.path.toUpperCase()} · ${h.flower||ELEMENTS[h.element].name}</span><h2>${h.name}</h2><p>${h.description||h.title}</p><div class="detail-stats">${[['hp','Vitality'],['atk','Attack'],['def','Defense'],['haste','Haste']].map(([k,l])=>`<div><span>${l}</span><strong>${num(stats[k])}</strong></div>`).join('')}</div>${o?`<div class="growth-line"><span>Level <b>${o.level}</b> / ${(o.realm+1)*10}</span><span>${(Store.REALMS[o.realm]?.name||Store.REALMS[o.realm])??'Qi Refining'}</span><span>Dao petals ${o.petals}/6</span></div><div class="growth-actions">${[['level','Cultivate'],['realm','Breakthrough'],['meridian','Meridians'],['petal','Dao Blossom'],['bond','Share tea']].map(([track,label])=>button(label,'upgrade','subtle',`data-id="${h.id}" data-track="${track}"`)).join('')}</div>`:'<p class="not-owned">Follow her thread in the Fate Pond to invite her to your Pavilion.</p>'}<h3>Techniques</h3>${h.skills.map((s,i)=>`<div class="technique-detail"><span class="technique-icon">${['✧','❖','✺'][i]}</span><div><strong>${s.name} ${o?`<small>+${o.mastery[i]||0}</small>`:''}</strong><p>${s.description}</p><small>${s.cooldown} turn cooldown · ${s.target.replaceAll('-',' ')}</small></div>${o?button('+','mastery','round',`data-id="${h.id}" data-index="${i}" aria-label="Improve ${s.name}"`):''}</div>`).join('')}<h3>Innate seals</h3>${h.passives.map((p,i)=>`<p class="passive ${o?.level>=(i?50:30)?'unlocked':''}"><strong>◇ ${p.name}</strong> · Lv. ${i?50:30}<br>${p.description}</p>`).join('')}${o?`<h3>Equipment · ${Object.keys(o.equipment||{}).length}/10</h3><div class="equipment-slots">${Store.GEAR_SLOTS.map(slot=>`<button data-action="equip-slot" data-id="${h.id}" data-slot="${typeof slot==='string'?slot:slot.id}">${icon('shield')}<span>${typeof slot==='string'?slot:slot.name}</span><small>${o.equipment[typeof slot==='string'?slot:slot.id]?'Equipped':'Empty'}</small></button>`).join('')}</div>`:''}</div>`;}
  else if(m.type==='mode'){const mode=MODES.find(x=>x.id===m.id);heading=mode.name;body=`<div class="mode-modal-art mode-art mode-${mode.id}"></div><span class="eyebrow">${mode.subtitle}</span><p>${mode.description}</p><div class="difficulty-row"><span>${mode.id==='pagoda'?'Floor':'Difficulty'}</span><button data-action="difficulty" data-change="-1">−</button><strong>${difficulty}</strong><button data-action="difficulty" data-change="1">+</button><span>/ ${mode.maxLevel}</span></div><p class="reward-line">${icon('gift')}${mode.reward}</p><div class="modal-buttons">${button('Edit formation','navigate','jade','data-screen="formation"')}${mode.id==='realm'?button('Enter the Secret Realm','navigate','primary','data-screen="realm"'):button('Begin challenge ❯','battle-start','primary',`data-id="${mode.id}"`)}${button('Sweep cleared stage','sweep','subtle',`data-id="${mode.id}"`)}</div>`;}
  else if(m.type==='rates'){heading='The threads are in your favor';body=`<div class="rates"><div><b>3%</b><span>5★ Celestial</span></div><div><b>15%</b><span>4★ Bloom</span></div><div><b>82%</b><span>3★ Bud</span></div></div><p>A ten-summon guarantees at least one 4★. From summon 50, Celestial odds increase by 5 percentage points per pull. Summon 60 is guaranteed.</p><p>The featured heroine receives half of all Celestial results. Every 120 Fate Points lets you choose any Celestial. Duplicates open a Dao petal; excess copies become Blossom Dew.</p><p>All currency is earned in play. All thirty heroines remain in the permanent pool.</p>`;}
  else if(m.type==='history'){heading='Threads of fate';body=`<div class="history scroll-area">${state.summonHistory.slice(0,60).map(r=>{const h=getHero(r.id||r.heroId);return `<div><strong>${h?.name||r.name||'Blossom'}</strong><span class="stars">${'✦'.repeat(h?.rarity||r.rarity||3)}</span><small>${r.isNew?'New thread':'Fated encounter'}</small></div>`;}).join('')||'<p>No threads have been drawn yet.</p>'}</div>`;}
  else if(m.type==='reveal'){heading='Destiny blooms';cls='reveal-modal';body=`<div class="summon-result-grid">${m.heroes.map((r,i)=>`<div class="summon-result" style="animation-delay:${i*.1}s">${card(getHero(r.id),{action:'hero'})}<span>${r.isNew?'✦ New Blossom':r.dew?'+'+r.dew+' Blossom Dew':'Dao petal awakened'}</span></div>`).join('')}</div><p>Every thread brings your Pavilion closer to full bloom.</p>${button('Continue','close','primary')}`;}
  else if(m.type==='settings'){heading='Pavilion settings';const cutins=typeof state.settings.cutins==='boolean'?(state.settings.cutins?'always':'never'):state.settings.cutins;body=`<div class="settings-list">${[['sound','Sound effects'],['music','Ambient music'],['reducedMotion','Reduce motion']].map(([key,label])=>`<label><span>${label}</span><input type="checkbox" data-setting="${key}" ${state.settings[key]?'checked':''}></label>`).join('')}<label><span>Ultimate cut-ins</span><select data-setting="cutins">${[['always','Every ultimate'],['first','First use per battle'],['never','Never']].map(([value,label])=>`<option value="${value}" ${cutins===value?'selected':''}>${label}</option>`).join('')}</select></label><label><span>Volume</span><input type="range" data-setting="volume" min="0" max="1" step="0.05" value="${state.settings.volume??.5}"></label><label><span>Battle speed</span><select data-setting="speed"><option value="1" ${state.settings.speed===1?'selected':''}>×1 · Cinematic</option><option value="2" ${state.settings.speed===2?'selected':''}>×2 · Swift</option><option value="3" ${state.settings.speed===3?'selected':''}>×3 · Instant</option></select></label></div><div class="modal-buttons">${button('Export save','export','jade')}${button('Import save','import','subtle')}${button('Fullscreen','fullscreen','subtle')}</div><p class="fine">Autosaves after every transaction and turn. All content and progress stay on this PC.</p>${state.saveWarning?`<p>${esc(state.saveWarning)}</p>`:''}<input type="file" id="save-import" accept=".json" hidden>`;}
  else if(m.type==='duties'){heading='Sect duties';body=`<p>A little dedication makes a garden flourish.</p><div class="duties">${Store.DUTIES.map(q=>{const claimed=state.quests.claimed.includes(q.id),done=(state.quests.counts[q.metric]||0)>=q.target;return `<div><span>${icon('scroll')}</span><div><strong>${q.name} · ${Math.min(q.target,state.quests.counts[q.metric]||0)}/${q.target}</strong><p>${q.description}<br><small>${costs(q.reward)}</small></p></div>${button(claimed?'Claimed':'Claim','claim-duty','jade',`data-id="${q.id}" ${claimed||!done?'disabled':''}`)}</div>`;}).join('')}</div><div class="modal-buttons">${button(state.quests.chest?'Daily chest claimed':'Open daily chest · Complete all five duties','claim-duty','primary',`data-id="chest" ${state.quests.chest?'disabled':''}`)}</div>`;}
  else if(m.type==='ascension'){heading='Path of Ascension';body=`<p>Every tier is free. Earn Ascension EXP through battles, duties and cultivation.<br><strong>${num(state.progress.ascensionXp)} Ascension EXP</strong></p><div class="ascension-grid">${Array.from({length:30},(_,i)=>{const tier=i+1,claimed=state.progress.ascensionClaimed.includes(tier);return `<div class="ornamental"><span>Tier ${tier}</span>${icon('gift')}<strong>${num(tier*150)} EXP</strong>${button(claimed?'Claimed':'Claim rewards','claim-tier','subtle',`data-index="${tier}" ${claimed||state.progress.ascensionXp<tier*150?'disabled':''}`)}</div>`;}).join('')}</div>`;}
  else if(m.type==='daily'){heading='Daily incense';body=`<div class="daily-lotus">${icon('lotus')}</div><h2>Another day beneath the same moon</h2><p>Light a stick of incense and receive your daily blessing.<br>Your streak does not reset when you take a break.</p>${button('Receive blessing','claim-daily','primary')}`;}
  else if(m.type==='mail'){heading='Jade slips';body=`<article class="letter"><span class="eyebrow">FROM SU LIANHUA</span><h3>Welcome home, Pavilion Master.</h3><p>The lotus pond is clear again, and the others are waiting in the courtyard. Take all the time you need. A flower never hurries to bloom.</p><p>Four founding Blossoms, Fate Incense, cultivation supplies and your first equipment have already been placed in your storage ring.</p></article><article class="letter"><span class="eyebrow">PAVILION NOTICE</span><h3>The gates to the realms are open</h3><p>Begin with a Demon Hunt or an elemental shrine. Use Water → Wood → Fire → Earth to form your first Harmony chain. Every ready technique can be cast during your turn.</p></article>`;}
  else if(m.type==='shop'){heading='Merit exchange';body=`<p>Trade resources earned through your adventures.</p><div class="shop-grid">${Store.SHOP_ITEMS.map(i=>`<div class="ornamental">${icon('gift')}<h3>${i.name}</h3><p>${i.description||''}</p><p class="fine">${costs(i.cost)}</p>${button('Exchange','buy','jade',`data-id="${i.id}"`)}</div>`).join('')}</div>`;}
  else if(m.type==='gear'){const g=state.inventory.find(x=>x.id===m.id);if(!g)return '';const owner=Object.entries(state.heroes).find(([,o])=>Object.values(o.equipment).includes(g.id));heading=g.name;body=`<div class="gear-hero-symbol">${icon(g.slot==='weapon'?'sword':'shield')}</div><span class="eyebrow">${g.rarity} · Tier ${g.tier} · ${g.slot} · +${g.level}</span><p>${Object.entries(g.stats||{}).map(([k,v])=>statText(k,v)).join(' · ')}</p><p>Roll quality ${g.quality}% · ${owner?'Equipped by '+getHero(owner[0]).name:'Unequipped'}${g.locked?' · Locked':''}</p><div class="modal-buttons">${button('Refine · '+num(400*(g.level+1)*g.tier)+' stones + '+(2+g.level)+' dust','refine','jade',`data-id="${g.id}" ${g.level>=15?'disabled':''}`)}${button(g.locked?'Unlock':'Lock','gear-lock','subtle',`data-id="${g.id}"`)}${button('Salvage','salvage','subtle',`data-id="${g.id}" ${owner||g.locked?'disabled':''}`)}${owner?button('Unequip','unequip','subtle',`data-id="${owner[0]}" data-slot="${g.slot}"`):''}</div><h3>Equip on a Blossom</h3><div class="equip-heroes">${Object.keys(state.heroes).map(id=>button(getHero(id).name,'equip','subtle',`data-id="${g.id}" data-hero="${id}"`)).join('')}</div>`;}
  else if(m.type==='equip-list'){heading='Choose '+m.slot;body=`<div class="equip-heroes">${state.inventory.filter(g=>g.slot===m.slot).map(g=>button(g.name+' +'+(g.level||0),'equip','subtle',`data-id="${g.id}" data-hero="${m.id}"`)).join('')||'<p>No equipment for this slot yet. Explore Demon Hunts to find more.</p>'}</div>`;}
  else if(m.type==='fate-select'){heading='Choose your celestial thread';body=`<p>120 Fate Points · Choose any Celestial Blossom.</p><div class="fate-select-grid">${HEROES.filter(h=>h.rarity===5).map(h=>card(h,{small:true,action:'fate-pick'})).join('')}</div>`;}
  else if(m.type==='encounter'){heading='A fortuitous encounter';body=`<p>Spend Spirit Qi on a blessing. One purchase per encounter.</p><div class="encounter-grid">${battle.encounters.map(e=>`<div class="ornamental">${icon('scroll')}<h3>${e.name}</h3><p>${e.description||e.effect||''}</p>${button((e.cost||5)+' Spirit Qi','encounter-buy','jade',`data-id="${e.id}"`)}</div>`).join('')}</div>`;}
  else if(m.type==='battle-log'){heading='Records of the duel';body=`<div class="history scroll-area">${battle.log.slice(-50).reverse().map(l=>`<p>${esc(typeof l==='string'?l:l.text||l.message||JSON.stringify(l))}</p>`).join('')}</div>`;}
  else if(m.type==='result'){const victory=battle.result==='victory';heading=victory?'The heavens bear witness':'The Dao is a patient teacher';cls='result-modal';body=`<div class="victory-seal">${victory?'勝':'修'}</div><h2>${victory?'VICTORY':'CHALLENGE ENDED'}</h2><p>${victory?'Your Blossoms have overcome this trial.':'Cultivate your Blossoms, refine your formation, and try again.'}</p>${reward?.ok?`<div class="reward-grid">${[['stones','Spirit Stones','coins'],['jade','Immortal Jade','diamond'],['incense','Fate Incense','scroll'],['exp','Experience','lotus']].map(([k,l,i])=>`<div>${icon(i)}<b>+${num(reward[k])}</b><span>${l}</span></div>`).join('')}</div>${reward.gear?`<p>Treasure discovered: ${reward.gear.rarity} ${reward.gear.name}</p>`:''}`:''}<div class="modal-buttons">${button('Return to Pavilion','navigate','jade','data-screen="home"')}${battle.mode==='realm'?button(victory?'Choose your blessing':'Return to Secret Realm','realm-continue','primary'):battle.mode==='tribulation'&&victory?button('Complete breakthrough','upgrade','primary',`data-id="${battle.heroId}" data-track="realm"`):battle.mode==='tribulation'?button('Challenge again','trial-launch','primary',`data-id="${battle.heroId}"`):button('Challenge again','battle-start','primary',`data-id="${battle.mode}"`)}</div>`;}
  else if(m.type==='leave-battle'){heading='Leave this trial?';body=`<p>Unfinished trials grant no rewards. Your resources will be kept.</p><div class="modal-buttons">${button('Continue battle','close','jade')}${button('Return to Pavilion','abandon','subtle')}</div>`;}
  else if(m.type==='profile'){heading='Pavilion Master';body=`<label class="name-field">Your name<input id="player-name" maxlength="24" value="${esc(state.player.name)}"></label>${button('Save name','rename','jade')}<p>Level ${state.player.level} · ${num(Store.getPower(state))} formation power</p>`;}
  else if(m.type==='blessing'){heading='A gift beyond the veil';const choices=(state.realmRun?.blessingChoices||[]).map(id=>Store.REALM_BLESSINGS.find(b=>b.id===id)).filter(Boolean);body=`<p>Choose one blessing for the rest of this expedition.</p><div class="encounter-grid">${choices.map(b=>`<div class="ornamental"><h3>${b.name}</h3><p>${b.description}</p>${button('Accept blessing','blessing','jade',`data-id="${b.id}"`)}</div>`).join('')}</div>`;}
  else if(m.type==='tribulation'){const h=getHero(m.id);heading='Face your Heart Demon';body=`<div class="daily-lotus">${icon('flame')}</div><h2>${h.name} · Heavenly Tribulation</h2><p>A major breakthrough requires victory over the shadow of your own Dao. Your three allies stand with you. Defeat the Heart Demon, then complete the breakthrough.</p><p>Retry freely. Defeat costs no resources.</p>${button('Enter tribulation','trial-launch','primary',`data-id="${h.id}"`)}`;}
  else if(m.type==='alchemy'){heading='Alchemy Pavilion';body=`<div class="daily-lotus">${icon('flame')}</div><p>Distill spirit herbs into Qi Gathering Pills.<br>Every pill costs 3 Spirit Herbs and 100 Spirit Stones. Fine and perfect brews yield extra pills.</p><p>${num(state.currencies.herbs)} herbs · ${num(state.currencies.pills)} pills in storage</p><div class="modal-buttons">${button('Brew one batch','brew','jade','data-count="1"')}${button('Brew ten batches','brew','primary','data-count="10"')}</div>`;}
  else if(m.type==='forge'){heading='Artefact Forge';const tier=Math.max(...Object.values(state.heroes).map(h=>h.realm+1));body=`<p>Choose an equipment slot and a set. Crafted treasures match your highest cultivation realm.</p><div class="settings-list"><label><span>Equipment slot</span><select id="craft-slot">${Store.GEAR_SLOTS.map(slot=>`<option value="${slot}">${slot}</option>`).join('')}</select></label><label><span>Equipment set</span><select id="craft-set">${Store.GEAR_SETS.map(set=>`<option value="${set}">${set}</option>`).join('')}</select></label></div><p>Tier ${tier} · ${num(3000*tier)} Spirit Stones + 20 Forging Dust</p>${button('Forge treasure','craft','primary')}`;}
  else if(m.type==='expeditions'){heading='Mission Hall';const active=state.expeditions.flatMap(e=>e.heroes);body=`<p>Send two to four Blossoms to gather supplies. They can still join battles.</p><div class="duties">${state.expeditions.map(e=>`<div><div><strong>${e.heroes.map(id=>getHero(id).name).join(' · ')}</strong><p>${Date.now()>=e.end?'Expedition complete':Math.ceil((e.end-Date.now())/60000)+' minutes remaining'}</p></div>${button('Collect','expedition-claim','jade',`data-id="${e.id}" ${Date.now()<e.end?'disabled':''}`)}</div>`).join('')}</div><div class="settings-list">${Object.keys(state.heroes).map(id=>`<label><span>${getHero(id).name}${active.includes(id)?' · On expedition':''}</span><input class="expedition-hero" type="checkbox" value="${id}" ${active.includes(id)?'disabled':''}></label>`).join('')}<label><span>Duration</span><select id="expedition-duration">${[1,4,8,12].map(hours=>`<option value="${hours}">${hours} hour${hours>1?'s':''}</option>`).join('')}</select></label></div>${button('Dispatch expedition','expedition-start','primary')}`;}
  else if(m.type==='realm-abandon'){heading='Leave the Secret Realm?';body=`<p>This ends your current expedition and its blessings. Treasures already earned remain in your storage ring.</p><div class="modal-buttons">${button('Keep exploring','close','jade')}${button('Abandon expedition','realm-abandon-confirm','subtle')}</div>`;}
  else if(m.type==='salvage-confirm'){const g=state.inventory.find(g=>g.id===m.id);heading='Salvage this treasure?';body=`<p>${g?.name} will be converted into Spirit Stones and Forging Dust.</p><div class="modal-buttons">${button('Keep treasure','close','jade')}${button('Salvage treasure','salvage-confirm','subtle',`data-id="${m.id}"`)}</div>`;}

  return `<div class="modal-backdrop"><section class="modal ornamental ${cls}" role="dialog" aria-modal="true" aria-label="${esc(heading)}"><button class="modal-close round" data-action="close" aria-label="Close">${icon('close')}</button>${m.type==='hero'?'':`<div class="modal-heading"><span>✦</span><h2>${heading}</h2><span>✦</span></div>`}<div class="modal-body">${body}</div></section></div>`;
}

async function startBattle(id,heroId=null){
  if(busy)return;modal=null;modeId=id;selectedSkill=null;reward=null;auto=false;playEvents.token=(playEvents.token||0)+1;fx.reset();
  let team=Store.resolveTeam(state);
  if(id==='tribulation'&&heroId&&!team.some(h=>h.id===heroId)){const h=getHero(heroId),owned=state.heroes[heroId];if(!h||!owned){toast('This Blossom has not joined your Pavilion.');return;}team=[{...h,...owned,...Store.getHeroStats(state,heroId)},...team.slice(0,3)];}
  battle=createBattle({team,mode:id,heroId,level:difficulty,array:state.array,seed:Date.now(),buffs:id==='realm'?Store.getRealmBuffs(state):{}});
  if(id==='realm'&&state.realmRun?.health?.length)for(const ally of battle.allies){const previous=state.realmRun.health.find(h=>h.id===ally.id);if(previous)ally.hp=Math.max(0,Math.round(ally.maxHp*previous.hp/Math.max(1,previous.maxHp)));}
  state.activeBattle=battle;screen='battle';busy=false;persist();render();toast('Your turn · Cast in Water → Wood → Fire → Earth order to build Harmony.');
}
async function resumeBattle(){
  const saved=state.activeBattle;if(!saved||!Array.isArray(saved.allies)||!Array.isArray(saved.enemies)||saved.allies.length===0){toast('No unfinished trial is available.');return;}
  playEvents.token=(playEvents.token||0)+1;fx.reset();battle=saved;screen='battle';modeId=saved.mode;difficulty=saved.level;selectedSkill=null;reward=null;auto=false;busy=false;modal=null;render();
  if(battle.result)await playEvents([]);else toast('Trial resumed · Round '+battle.round+' · Wave '+battle.wave);
}
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function playEvents(events=[]){
  const current=battle,token=playEvents.token=(playEvents.token||0)+1;busy=true;
  const currentView=()=>battle===current&&playEvents.token===token&&screen==='battle';
  // Commit the resolved action before playing its visuals. A process exit cannot
  // reroll a cast or lose a victory, and rewardBattle has its own duplicate guard.
  if(current.result){auto=false;if(!current.rewardsProcessed){current.rewardsProcessed=true;if(current.result==='victory'){current.rewardResult=Store.rewardBattle(state,current);}else if(current.mode==='realm'&&state.realmRun){state.realmRun.status='defeat';}}reward=current.rewardResult||null;state.activeBattle=null;}else state.activeBattle=current;
  persist();
  try{
    for(const e of events){if(!currentView())return;
      if(e.type==='skill'||e.type==='cast'){
        current.seenCutins ||= [];const preference=state.settings.cutins,cutinOn=preference!==false&&preference!=='never'&&(preference!=='first'||!current.seenCutins.includes(e.source));
        if(e.ultimate&&cutinOn&&!state.settings.reducedMotion){const actor=[...current.allies,...current.enemies].find(u=>u.uid===e.source),cut=document.querySelector('#cutin-layer');if(cut){const heroArt=HERO_ART[actor?.id]?actor.id:(HERO_ART[actor?.id?.replace(/^heart_/,'')]?actor.id.replace(/^heart_/,''):(e.art||actor?.art||'lotus'));cut.innerHTML=`<div class="ultimate-cutin" style="--phase:${ELEMENTS[e.element]?.color||'#ffe0aa'}">${e.boss&&heroArt==='hunt'?'<div class="boss-art"></div>':art(heroArt)}<div><span>DAO MANIFESTATION</span><h2>${esc(e.skill||actor?.skills?.[2]?.name||'Heavenly Technique')}</h2><p>${esc(e.name||actor?.name||'Celestial spirit')} · ${ELEMENTS[e.element]?.name||'Spirit'}</p></div></div>`;current.seenCutins.push(e.source);await delay(760/state.settings.speed);if(!currentView())return;cut.innerHTML='';}}
        const duration=fx.cast(e);await delay(Math.min(duration,e.ultimate?900:520)/state.settings.speed);
      }else if(e.type==='damage'||e.type==='heal'){fx.impact(e);await delay((e.hits>1?75:95)/state.settings.speed);}
      else{fx.feedback(e);if(['shatter','combo','wave','revive'].includes(e.type))await delay(350/state.settings.speed);if(e.type==='wave'&&currentView()){render();fx.feedback(e);}}
    }
    await delay(160/state.settings.speed);if(!currentView())return;busy=false;persist();render();if(current.result){if(current.result==='victory')fx.sound('victory');openModal('result');}
  }finally{if(battle===current&&playEvents.token===token)busy=false;}
}
async function useSkill(uid,index,target){if(busy||!battle||battle.result||modal||auto)return;const empower=index>0&&!!document.querySelector('#empower')?.checked;const res=castSkill(battle,uid,index,target,{empower});if(!res.ok){toast(res.reason);return;}selectedSkill=null;await playEvents(res.events);}
async function finishTurn(){if(busy||!battle||battle.result||modal)return;selectedSkill=null;const events=endTurn(battle);await playEvents(events.events||events);}
async function autoLoop(){
  if(autoLoop.running)return;autoLoop.running=true;
  try{while(auto&&screen==='battle'&&battle&&!battle.result){if(modal)break;if(busy){await delay(150);continue;}const next=autoAction(battle);if(next){const res=castSkill(battle,next.actorId,next.skillIndex,next.targetId,{empower:next.empower});if(res.ok)await playEvents(res.events);else{auto=false;toast(res.reason);}}else await finishTurn();if(auto)await delay(80);}}finally{autoLoop.running=false;}
}
game.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;fx.sound('click');if(state.settings.music&&!fx.musicTimer)fx.music(true);
  if(a==='navigate')navigate(b.dataset.screen);
  else if(a==='close')closeModal();
  else if(['settings','duties','ascension','daily','mail','rates','history','shop','profile','fate-select','records','alchemy','forge','expeditions','realm-abandon'].includes(a))openModal(a);
  else if(a==='currency')openModal(id==='incense'?'rates':'shop');
  else if(a==='hero')openModal('hero',{id});
  else if(a==='filter'){filter=id;render();}
  else if(a==='slot'){formationSlot=Number(b.dataset.slot);render();}
  else if(a==='assign'){const old=state.team.indexOf(id),current=state.team[formationSlot];state.team[formationSlot]=id;if(old>=0&&old!==formationSlot)state.team[old]=current;persist();render();}
  else if(a==='array'){state.array=id;persist();render();}
  else if(a==='auto-team'){state.team=['ling_shuang','mo_yingyue','yan_feihong','su_lianhua'];persist();render();toast('Water → Wood → Fire → Earth. Harmony formation ready.');}
  else if(a==='save-team'){persist();toast('Formation saved. Your immortals are ready.');}
  else if(a==='mode'){modeId=id;difficulty=Math.min(MODES.find(m=>m.id===id).maxLevel,(state.progress[id]||0)+1);openModal('mode',{id});}
  else if(a==='difficulty'){difficulty=Math.max(1,Math.min(MODES.find(m=>m.id===modeId).maxLevel,difficulty+Number(b.dataset.change)));openModal('mode',{id:modeId});}
  else if(a==='battle-start')await startBattle(id);
  else if(a==='resume-battle')await resumeBattle();
  else if(a==='skill'){if(busy||auto||!battle||battle.result)return;const uid=b.dataset.uid,index=Number(b.dataset.index),u=battle.allies.find(u=>u.uid===uid);if(!u||u.hp<=0)return;if(u.skipped){toast('This cultivator is sealed for the rest of this turn.');return;}if(u.cooldowns[index]>0){toast('This technique is recharging.');return;}battle.uiEmpower=!!document.querySelector('#empower')?.checked;if(selectedSkill?.actorId===uid&&selectedSkill.skillIndex===index&&u.skills[index].target.startsWith('all'))await useSkill(uid,index,u.skills[index].target==='all-allies'?battle.allies.find(u=>u.hp>0)?.uid:battle.enemies.find(u=>u.hp>0)?.uid);else{selectedSkill={actorId:uid,skillIndex:index};render();toast(u.skills[index].target.startsWith('all')?'Click the technique again to cast on all targets.':'Choose a '+(u.skills[index].target==='ally'?'friendly':'hostile')+' card.');}}
  else if(a==='target'){if(busy||auto||!battle)return;if(selectedSkill)await useSkill(selectedSkill.actorId,selectedSkill.skillIndex,b.dataset.uid);else{const u=[...battle.allies,...battle.enemies].find(x=>x.uid===b.dataset.uid);if(!u)return;toast(u.name+' · '+ELEMENTS[u.element].name+' · ATK '+num(u.atk)+' · DEF '+num(u.def)+' · Haste '+num(u.haste));}}
  else if(a==='end-turn')await finishTurn();
  else if(a==='auto'){auto=!auto;if(!busy)render();else toast(auto?'Auto battle enabled.':'Auto battle will stop after this technique.');if(auto)autoLoop();}
  else if(a==='speed'){state.settings.speed=state.settings.speed%3+1;persist();if(!busy)render();else toast('Battle speed ×'+state.settings.speed);}
  else if(a==='leave-battle'){auto=false;if(busy){toast('The current technique is resolving.');return;}openModal('leave-battle');}
  else if(a==='abandon'){auto=false;playEvents.token=(playEvents.token||0)+1;fx.reset();state.activeBattle=null;if(battle?.mode==='realm'&&state.realmRun)state.realmRun.status='defeat';busy=false;navigate('home');}
  else if(a==='battle-log'){if(!busy){auto=false;openModal('battle-log');}}
  else if(a==='encounter'){if(!busy){auto=false;openModal('encounter');}}
  else if(a==='encounter-buy'){if(busy)return;const res=buyEncounter(battle,id,battle.allies.find(u=>u.hp>0)?.uid);if(res.ok){closeModal();await playEvents(res.events||[]);}else toast(res.reason);}
  else if(a==='summon'){const res=Store.summon(state,Number(b.dataset.count),'gui_chanjuan');if(res.ok){persist();render();fx.sound('summon');fx.burst(800,450,'#ffe4a0',150,2);await delay(state.settings.reducedMotion?0:650);openModal('reveal',{heroes:res.heroes});}else toast(res.reason);}
  else if(a==='upgrade'||a==='mastery'){const track=a==='mastery'?'mastery':b.dataset.track;const res=Store.upgradeHero(state,id,track,Number(b.dataset.index)||0);if(res.needsTrial){openModal('tribulation',{id});}else if(act(res)){if(screen==='battle'&&battle?.result)navigate('collection');openModal('hero',{id});toast(res.message||'Cultivation deepens.');}}
  else if(a==='trial-launch'){difficulty=state.heroes[id].level;await startBattle('tribulation',id);}
  else if(a==='gear')openModal('gear',{id});
  else if(a==='equip-slot')openModal('equip-list',{id,slot:b.dataset.slot});
  else if(a==='equip'){if(act(Store.equipGear(state,b.dataset.hero,id),'Treasure equipped.'))openModal('hero',{id:b.dataset.hero});}
  else if(a==='refine'){if(act(Store.upgradeGear(state,id),'Equipment refined.'))openModal('gear',{id});}
  else if(a==='gear-lock'){const gear=state.inventory.find(g=>g.id===id);gear.locked=!gear.locked;persist();openModal('gear',{id});}
  else if(a==='unequip'){if(act(Store.unequipGear(state,id,b.dataset.slot),'Treasure unequipped.'))openModal('hero',{id});}
  else if(a==='salvage')openModal('salvage-confirm',{id});
  else if(a==='salvage-confirm'){const res=Store.salvageGear(state,id);if(res.ok){modal=null;act(res,'Treasure salvaged.');}else toast(res.reason);}
  else if(a==='buy'){if(act(Store.buyItem(state,id),'Exchange complete.'))openModal('shop');}
  else if(a==='claim-duty'){if(act(Store.claimDuty(state,id),'Duty rewards received.'))openModal('duties');}
  else if(a==='claim-tier'){if(act(Store.claimAscension(state,Number(b.dataset.index)),'Ascension rewards received.'))openModal('ascension');}
  else if(a==='claim-daily'){act(Store.claimDaily(state),'Your daily blessing has been received.');}
  else if(a==='idle'){const res=Store.claimIdle(state);act(res,res.ok===false?undefined:'The Pavilion’s gathered resources have been collected.');}
  else if(a==='building')act(Store.upgradeBuilding(state,id),'Pavilion improved.');
  else if(a==='brew'){const res=Store.brewPills(state,Number(b.dataset.count));if(act(res)){openModal('alchemy');toast(res.pills+' spirit pills brewed.');}}
  else if(a==='craft'){const res=Store.craftGear(state,document.querySelector('#craft-slot').value,document.querySelector('#craft-set').value);if(act(res)){openModal('gear',{id:res.gear.id});toast('A new treasure is forged.');}}
  else if(a==='expedition-start'){const heroes=[...document.querySelectorAll('.expedition-hero:checked')].map(el=>el.value);const res=Store.startExpedition(state,heroes,Number(document.querySelector('#expedition-duration').value));if(act(res,'Expedition dispatched.'))openModal('expeditions');}
  else if(a==='expedition-claim'){if(act(Store.claimExpedition(state,id),'Expedition rewards received.'))openModal('expeditions');}
  else if(a==='sweep')act(Store.sweepStage(state,id,difficulty),'Sweep complete. Rewards added to your storage ring.');
  else if(a==='fate-pick')act(Store.selectFateHero(state,id),'Your celestial thread has found its Blossom.');
  else if(a==='realm-start'){const res=Store.startRealmRun(state);if(res.ok){modal=null;screen='realm';act(res);}else toast(res.reason);}
  else if(a==='realm-node'){const res=Store.chooseRealmNode(state,Number(b.dataset.index));if(!res.ok){toast(res.reason);return;}persist();if(res.battle){difficulty=res.battle.level;await startBattle('realm');}else{render();toast(res.healed?'Your formation has recovered its health.':res.gear?'Treasure discovered: '+res.gear.name:'Your expedition continues.');}}
  else if(a==='realm-enter'){const run=state.realmRun;difficulty=run.floor+(run.nodes[run.selected]?.type==='elite'?1:0);await startBattle('realm');}
  else if(a==='realm-blessing')openModal('blessing');
  else if(a==='realm-continue'){navigate('realm');if(state.realmRun?.status==='blessing')openModal('blessing');}
  else if(a==='realm-abandon-confirm'){Store.abandonRealm(state);if(state.activeBattle?.mode==='realm')state.activeBattle=null;navigate('realm');}
  else if(a==='blessing'){const res=Store.applyRealmBlessing(state,id);if(res.ok){modal=null;screen='realm';act(res,state.realmRun.status==='complete'?'Secret Realm conquered. Expedition rewards received.':'Blessing accepted.');}else toast(res.reason);}
  else if(a==='export'){try{const text=Store.exportSave(state);if(window.desktop?.exportSave){if(await window.desktop.exportSave(text))toast('Save exported.');}else{const blob=new Blob([text],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='immortal-blossoms-save.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Save exported.');}}catch(error){toast('Could not export save: '+error.message);}}
  else if(a==='import'){if(window.desktop?.importSave){try{const text=await window.desktop.importSave();if(text){state=Store.importSave(text);battle=null;auto=false;persist();navigate('home');toast('Save restored.');}}catch(error){toast('Could not restore save: '+error.message);}}else document.querySelector('#save-import').click();}
  else if(a==='fullscreen'){try{if(window.desktop?.setFullscreen){state.settings.fullscreen=await window.desktop.setFullscreen(!state.settings.fullscreen);}else if(!document.fullscreenElement){await document.documentElement.requestFullscreen();state.settings.fullscreen=true;}else{await document.exitFullscreen();state.settings.fullscreen=false;}persist();}catch(error){toast('Fullscreen could not be changed: '+error.message);}}
  else if(a==='rename'){state.player.name=document.querySelector('#player-name').value.trim().slice(0,24)||'Pavilion Master';persist();closeModal();render();}
});
game.addEventListener('change',async e=>{const el=e.target;if(el.dataset.setting){const k=el.dataset.setting;state.settings[k]=el.type==='checkbox'?el.checked:k==='cutins'?el.value:Number(el.value);persist();if(k==='music')fx.music(el.checked);if(k==='reducedMotion')document.querySelector('#stage').classList.toggle('reduce-motion',el.checked);}if(el.id==='save-import'&&el.files[0]){try{const imported=Store.importSave(await el.files[0].text());if(imported.ok===false)throw Error(imported.reason);state=imported.state||imported;battle=null;auto=false;persist();navigate('home');toast('Save restored.');}catch(err){toast('Could not restore save: '+err.message);}}});
addEventListener('resize',resize);addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select'))return;if(e.key==='Escape'){if(modal)closeModal();else if(screen==='battle'){auto=false;if(busy){toast('The current technique is resolving.');return;}openModal('leave-battle');}else navigate('home');}if(screen==='battle'&&!modal){if(e.code==='Space'){e.preventDefault();finishTurn();}if(e.key.toLowerCase()==='a'){auto=!auto;if(!busy)render();if(auto)autoLoop();}}});
addEventListener('beforeunload',persist);render();
if(state.saveWarning)openModal('save-warning');
game.addEventListener('pointermove',event=>{if(state.settings.reducedMotion)return;const card=event.target.closest('.hero-card');if(!card)return;const rect=card.getBoundingClientRect(),x=(event.clientX-rect.left)/rect.width-.5,y=(event.clientY-rect.top)/rect.height-.5;card.style.transform=`perspective(650px) rotateX(${-y*7}deg) rotateY(${x*9}deg) translateY(-2px)`;});
game.addEventListener('pointerout',event=>{const card=event.target.closest('.hero-card');if(card&&!card.contains(event.relatedTarget))card.style.transform='';});
